#!/usr/bin/env bash
# Shared helpers for apply-host-identity.sh / verify-host-identity.sh.
# Presentation is generated by the C++ claudebox-identity engine (P3), not by
# a second policy implementation in Python.
# shellcheck shell=bash

# hide_identifiers remains a transitional guard: it is not a blanket
# "publish every identifier" switch. Per-field policy
# (CLAUDE_BOX_IDENTITY_POLICY or $prefix/var/host-identity.policy.yaml)
# is how a user opts in to expose or override individual fields.
# Mapping: true (default) → C++ default policy (model may be shown,
# identifiers hidden) unless a policy file overrides specific fields.
# false → still refused, so a raw inventory cannot be dumped wholesale.
claudebox_require_hide_identifiers() {
  case "${CLAUDE_BOX_HIDE_IDENTIFIERS:-true}" in
    true|True|TRUE|1|yes|Yes|on|On) ;;
    *)
      echo "error: host_identity.hide_identifiers must stay true (got ${CLAUDE_BOX_HIDE_IDENTIFIERS})" >&2
      echo "error: to show or change a field, use a per-field identity policy (expose / override); this flag is not a dump-all switch" >&2
      return 1
      ;;
  esac
}

claudebox_yaml_quote() {
  local s="$1"
  if [[ -z "$s" ]]; then
    printf '""'
    return
  fi
  case "$s" in
    *[:\#\{\}\[\]\&\*\!\|\>\'\"\%\@\`]*|*" "*)
      s="${s//\\/\\\\}"
      s="${s//\"/\\\"}"
      printf '"%s"' "$s"
      ;;
    *)
      printf '%s' "$s"
      ;;
  esac
}

# Inventory already names this canonical model field (any known alias).
claudebox_inventory_has_field() {
  local file="$1" field="$2"
  local pat
  case "$field" in
    manufacturer)
      pat='^(manufacturer|sys_vendor|vendor|system_manufacturer|win32_computersystem\.manufacturer)[[:space:]]*:'
      ;;
    product)
      pat='^(product|product_name|productname|model|system_product_name|win32_computersystem\.model)[[:space:]]*:'
      ;;
    *)
      pat="^${field}[[:space:]]*:"
      ;;
  esac
  grep -qiE "$pat" "$file"
}

# Print the path to an inventory file the C++ CLI can read.
# Never overwrites var/host-inventory.raw.yaml (collect's output).
# Env manufacturer/product only fill fields the inventory does not already have.
claudebox_resolve_inventory() {
  local prefix="$1"
  local inv="" work
  mkdir -p "$prefix/var"

  if [[ -n "${CLAUDE_BOX_HOST_INVENTORY:-}" && -f "${CLAUDE_BOX_HOST_INVENTORY}" ]]; then
    inv="${CLAUDE_BOX_HOST_INVENTORY}"
  elif [[ -f "$prefix/var/host-inventory.raw.yaml" ]]; then
    inv="$prefix/var/host-inventory.raw.yaml"
  fi

  local man="${CLAUDE_BOX_HOST_MANUFACTURER:-}"
  local prod="${CLAUDE_BOX_HOST_PRODUCT:-}"
  man="${man#"${man%%[![:space:]]*}"}"
  man="${man%"${man##*[![:space:]]}"}"
  prod="${prod#"${prod%%[![:space:]]*}"}"
  prod="${prod%"${prod##*[![:space:]]}"}"

  if [[ -n "$inv" ]]; then
    local need_man=0 need_prod=0
    if [[ -n "$man" ]] && ! claudebox_inventory_has_field "$inv" manufacturer; then
      need_man=1
    fi
    if [[ -n "$prod" ]] && ! claudebox_inventory_has_field "$inv" product; then
      need_prod=1
    fi
    if [[ "$need_man" -eq 0 && "$need_prod" -eq 0 ]]; then
      printf '%s\n' "$inv"
      return 0
    fi
    work="$prefix/var/.claudebox-apply-inventory.yaml"
    {
      cat "$inv"
      echo
      echo "# Env-filled model fields (not a collected raw inventory)."
      if [[ "$need_man" -eq 1 ]]; then
        printf 'manufacturer: %s\n' "$(claudebox_yaml_quote "$man")"
      fi
      if [[ "$need_prod" -eq 1 ]]; then
        printf 'product: %s\n' "$(claudebox_yaml_quote "$prod")"
      fi
    } > "$work"
    printf '%s\n' "$work"
    return 0
  fi

  work="$prefix/var/.claudebox-apply-inventory.yaml"
  {
    echo "# Synthesized inventory for apply/verify (not a collected raw inventory)."
    if [[ -n "$man" ]]; then
      printf 'manufacturer: %s\n' "$(claudebox_yaml_quote "$man")"
    fi
    if [[ -n "$prod" ]]; then
      printf 'product: %s\n' "$(claudebox_yaml_quote "$prod")"
    fi
  } > "$work"

  # Last-resort fallback: already-sanitized model from a previous apply.
  if [[ -z "$man" && -z "$prod" && -f "$prefix/var/host-identity.allowed.yaml" ]]; then
    cat "$prefix/var/host-identity.allowed.yaml" > "$work"
  fi
  printf '%s\n' "$work"
}

# Print policy path if one is configured; empty if the engine should use defaults.
claudebox_resolve_policy() {
  local prefix="$1"
  if [[ -n "${CLAUDE_BOX_IDENTITY_POLICY:-}" && -f "${CLAUDE_BOX_IDENTITY_POLICY}" ]]; then
    printf '%s\n' "${CLAUDE_BOX_IDENTITY_POLICY}"
    return 0
  fi
  if [[ -f "$prefix/var/host-identity.policy.yaml" ]]; then
    printf '%s\n' "$prefix/var/host-identity.policy.yaml"
    return 0
  fi
}

claudebox_try_build() {
  local src="$1"
  local build="$src/build"
  [[ -f "$src/CMakeLists.txt" ]] || return 1
  cmake -S "$src" -B "$build" >/dev/null
  cmake --build "$build" --target claudebox-identity >&2
}

# Print an executable path for claudebox-identity, or return 1.
claudebox_find_identity_bin() {
  local script_dir="${1:-}"
  local prefix="${CLAUDE_BOX_PREFIX:-}"
  local cand src

  if [[ -n "${CLAUDE_BOX_IDENTITY_BIN:-}" && -x "${CLAUDE_BOX_IDENTITY_BIN}" ]]; then
    printf '%s\n' "${CLAUDE_BOX_IDENTITY_BIN}"
    return 0
  fi
  if [[ -n "$prefix" && -x "$prefix/bin/claudebox-identity" ]]; then
    printf '%s\n' "$prefix/bin/claudebox-identity"
    return 0
  fi

  local roots=()
  [[ -n "${CLAUDE_BOX_REPO:-}" ]] && roots+=("${CLAUDE_BOX_REPO}")
  if [[ -n "${CLAUDE_BOX_CONFIG:-}" && -f "${CLAUDE_BOX_CONFIG}" ]]; then
    # .../src/wsl-box/config/file.yaml → repo
    roots+=("$(cd "$(dirname "${CLAUDE_BOX_CONFIG}")/../../.." && pwd)")
  fi
  if [[ -n "$script_dir" && -f "$script_dir/../../../claudebox/CMakeLists.txt" ]]; then
    # guest → wsl-box → src → repo
    roots+=("$(cd "$script_dir/../../.." && pwd)")
  fi

  local root
  for root in "${roots[@]}"; do
    cand="$root/src/claudebox/build/claudebox-identity"
    if [[ -x "$cand" ]]; then
      printf '%s\n' "$cand"
      return 0
    fi
    src="$root/src/claudebox"
    if [[ -f "$src/CMakeLists.txt" ]]; then
      echo "[claude-box] building claudebox-identity at $src/build" >&2
      if claudebox_try_build "$src" && [[ -x "$src/build/claudebox-identity" ]]; then
        printf '%s\n' "$src/build/claudebox-identity"
        return 0
      fi
    fi
  done

  echo "error: claudebox-identity not found." >&2
  echo "error: build with: cmake -S src/claudebox -B src/claudebox/build && cmake --build src/claudebox/build" >&2
  echo "error: or run src/wsl-box/linux/Install-ClaudeBoxFramework.sh (copies the binary to \$CLAUDE_BOX_PREFIX/bin)." >&2
  echo "error: override the path with CLAUDE_BOX_IDENTITY_BIN." >&2
  return 1
}

claudebox_identity_args() {
  local cmd="$1" inventory="$2" prefix="$3" policy="${4:-}"
  local args=("$cmd" --inventory "$inventory" --prefix "$prefix")
  if [[ -n "$policy" ]]; then
    args+=(--policy "$policy")
  fi
  printf '%s\0' "${args[@]}"
}
